def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]!=bg and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                out.append(comp)
    return out
def norm3(comp):
    rs=[r for r,_ in comp]; cs=[c for _,c in comp]
    r0,c0=min(rs),min(cs); h=max(rs)-r0+1; w=max(cs)-c0+1
    mat=[[0]*3 for _ in range(3)]
    for r,c in comp:
        # map relative position to 3x3
        rr=(r-r0)*2//h; cc=(c-c0)*2//w
        mat[rr][cc]=1
    return mat
for i in [1,2,3,4]:
